const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageBreak, Header, Footer, PageNumber } = require('docx');
const fs = require('fs');

// Brand colors
const NAVY = "1F2937";
const GOLD = "B8956A";
const SOFT_GRAY = "F5F3F0";
const MID_GRAY = "6B7280";
const ACCENT_BG = "FAF7F2";

// Helpers
const border = { style: BorderStyle.SINGLE, size: 4, color: "D4CFC4" };
const cellBorders = { top: border, bottom: border, left: border, right: border };

function H1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, bold: true, color: NAVY, size: 36 })],
    spacing: { before: 360, after: 180 }
  });
}

function H2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, bold: true, color: NAVY, size: 28 })],
    spacing: { before: 280, after: 140 }
  });
}

function H3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    children: [new TextRun({ text, bold: true, color: GOLD, size: 24 })],
    spacing: { before: 200, after: 100 }
  });
}

function P(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({ text, size: 22, color: "2A2A2A", ...opts })],
    spacing: { before: 60, after: 120, line: 320 }
  });
}

function PRun(runs, opts = {}) {
  return new Paragraph({
    children: runs,
    spacing: { before: 60, after: 120, line: 320 },
    ...opts
  });
}

function Bullet(text, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    children: [new TextRun({ text, size: 22, color: "2A2A2A" })],
    spacing: { before: 40, after: 80, line: 300 }
  });
}

function BulletRun(runs, level = 0) {
  return new Paragraph({
    numbering: { reference: "bullets", level },
    children: runs,
    spacing: { before: 40, after: 80, line: 300 }
  });
}

function Quote(text) {
  return new Paragraph({
    children: [new TextRun({ text, italics: true, size: 22, color: "3A3A3A" })],
    spacing: { before: 100, after: 140, line: 320 },
    indent: { left: 360 },
    border: { left: { style: BorderStyle.SINGLE, size: 18, color: GOLD, space: 12 } }
  });
}

function ScriptBlock(text) {
  // For sample scripts: indented, soft background feel via italics + spacing
  return new Paragraph({
    children: [new TextRun({ text, size: 22, color: "2A2A2A" })],
    spacing: { before: 80, after: 100, line: 320 },
    indent: { left: 360, right: 360 },
    border: {
      left: { style: BorderStyle.SINGLE, size: 12, color: NAVY, space: 12 }
    }
  });
}

function Callout(label, body) {
  // Table-as-callout box
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: {
              top: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
              bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
              left: { style: BorderStyle.SINGLE, size: 24, color: GOLD },
              right: { style: BorderStyle.SINGLE, size: 4, color: GOLD }
            },
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: ACCENT_BG, type: ShadingType.CLEAR },
            margins: { top: 160, bottom: 160, left: 240, right: 240 },
            children: [
              new Paragraph({
                children: [new TextRun({ text: label, bold: true, size: 20, color: GOLD, allCaps: true })],
                spacing: { after: 80 }
              }),
              new Paragraph({
                children: [new TextRun({ text: body, size: 22, color: "2A2A2A" })],
                spacing: { line: 320 }
              })
            ]
          })
        ]
      })
    ]
  });
}

function Spacer() {
  return new Paragraph({ children: [new TextRun({ text: "" })], spacing: { before: 80, after: 80 } });
}

function Divider() {
  return new Paragraph({
    children: [new TextRun({ text: "" })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 6 } },
    spacing: { before: 120, after: 120 }
  });
}

// =========================================================================
// CONTENT
// =========================================================================
const content = [];

// COVER
content.push(
  new Paragraph({ children: [new TextRun({ text: "" })], spacing: { before: 2400 } }),
  new Paragraph({
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 24, color: GOLD, allCaps: true, characterSpacing: 60 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 480 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "The Setter Playbook", bold: true, size: 60, color: NAVY })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 240 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Multi-Channel Outreach, Conversation, and Conversion", size: 28, color: MID_GRAY, italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 720 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Email. Phone. Text. Instagram DM. Facebook Groups. LinkedIn.", size: 22, color: "2A2A2A" })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 120 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Everything you need to open doors, hold real conversations, and book the right owners onto Bethany Anne's calendar.", size: 22, color: MID_GRAY, italics: true })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 1200 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Internal use. For referral partners and setters only.", size: 18, color: MID_GRAY })],
    alignment: AlignmentType.CENTER
  }),
  new Paragraph({
    children: [new TextRun({ text: "theluxoracollective.co", size: 18, color: GOLD, bold: true })],
    alignment: AlignmentType.CENTER
  }),
  new Paragraph({ children: [new PageBreak()] })
);

// SECTION: READ THIS FIRST
content.push(H1("Read this first"));
content.push(P("This is not a script you memorize. It is a posture you adopt."));
content.push(P("Your job is not to sell. Your job is to open a door, ask one real question, listen longer than feels comfortable, and decide if this owner belongs on Bethany Anne's calendar. The team handles everything from there."));
content.push(P("You are speaking peer-to-peer with med spa owners who have built something real. They have a team. They have revenue. They have pride. They have also been pitched by every marketing agency on the internet and they can smell a sales script in three seconds. That is why the words on these pages are the floor, not the ceiling. Read them, internalize the flow, then sound like a human who actually gives a damn."));
content.push(Spacer());
content.push(Callout("The one rule that runs everything",
  "You are not selling Luxora. You are introducing a real owner to a team that can see what they cannot see from inside their own business. If you ever feel yourself reaching for a close, stop. Ask another question instead."));
content.push(Spacer());

content.push(H2("The emotional posture you bring to every channel"));
content.push(P("Med spa owners do not need another vendor in their inbox. They need someone who gets it. The posture you carry into every message, call, and DM is what separates a setter who books calls from a setter who gets ignored."));
content.push(Spacer());

content.push(H3("Curiosity over claims"));
content.push(P("You are not telling owners what their problem is. You are asking them what their problem is. Even if you already know from their reviews, their staff turnover, their stagnant Instagram, or the comments on their Yelp page, you let them say it. The moment they put words to the friction, they own it. That is what makes them book."));

content.push(H3("Warmth over polish"));
content.push(P("Perfect grammar and a tight CTA reads as agency. A slightly looser, conversational message reads as a person. Use contractions. Drop a sentence fragment. Send a follow-up that says \"forgot to mention\" instead of a structured paragraph. The owners we want do not respond to brochures. They respond to people."));

content.push(H3("Conviction over pressure"));
content.push(P("You believe in Bethany Anne and the work. That belief is the only thing that lets you handle objections without flinching. When an owner says \"$29? Most people do these free,\" you do not get defensive. You agree, then explain why that is exactly the point. Conviction sounds like a calm \"yeah, and here is why.\" Pressure sounds like \"but wait, let me explain why you should.\""));

content.push(H3("Patience over pace"));
content.push(P("A booked call this week is worth ten chased leads next week. If an owner goes quiet after two thoughtful messages, you do not push. You move on or you circle back in 30 days with something genuinely new. The pipeline rewards owners who are ready, not owners who are exhausted."));

content.push(Spacer());
content.push(Callout("Internal reminder",
  "If you ever read one of your own messages back and it sounds like a brochure, an agency, or a salesperson trying to hit a quota, delete it and rewrite it. Read it out loud. If you would not say it to a friend over coffee, do not send it."));

content.push(new Paragraph({ children: [new PageBreak()] }));

// SECTION: WHO YOU ARE TARGETING
content.push(H1("Who you are targeting"));
content.push(P("Luxora is not for everyone, and pretending otherwise costs you credibility and wastes Bethany Anne's calendar. The owners below are the only ones worth your outreach time."));
content.push(Spacer());

content.push(H2("Reach out to these owners"));
content.push(Bullet("Independent med spa owners. The actual decision maker, not associates, not front desk."));
content.push(Bullet("Practices generating $500K to $2M annually."));
content.push(Bullet("Open at least 18 months. Not brand new."));
content.push(Bullet("Owners who care about scaling, not just keeping the lights on."));
content.push(Bullet("US-based practices."));

content.push(H2("Skip these"));
content.push(Bullet("Solo injectors with no team or location."));
content.push(Bullet("Practices doing under $300K. Too early."));
content.push(Bullet("Owners actively looking for a buyer or winding down."));
content.push(Bullet("Anyone who only wants a marketing agency."));
content.push(Bullet("Anyone who treats their staff like they are disposable. They will not implement the work."));

content.push(Spacer());
content.push(H2("Signals an owner is ready for this conversation"));
content.push(P("These are the green flags that tell you to keep going when you see them on a profile, a post, or in a reply."));
content.push(Bullet("They post about their team, not just themselves."));
content.push(Bullet("They mention growth, expansion, or wanting more time back."));
content.push(Bullet("They have a real website with services, pricing tiers, or packages already."));
content.push(Bullet("They show up in the business, but they are clearly the bottleneck."));
content.push(Bullet("They have shared frustration publicly about staff, no-shows, or inconsistent months."));

content.push(H2("Signals to skip and move on"));
content.push(Bullet("Their only content is selfies with filters and no business mentions."));
content.push(Bullet("They post about being slammed in a way that brags, not in a way that asks for help."));
content.push(Bullet("Their reviews show recurring complaints about staff rudeness and they defend the staff in replies."));
content.push(Bullet("They are looking for a one-time miracle, not a year-long partnership."));

content.push(new Paragraph({ children: [new PageBreak()] }));

// SECTION: THE CONVERSATION FRAMEWORK
content.push(H1("The conversation framework"));
content.push(P("This is the spine of every conversation across every channel. The words change. The order does not."));
content.push(Spacer());

content.push(H2("Phase 1: Open with curiosity, not a pitch"));
content.push(P("The goal of your first message, on any channel, is a reply. Nothing more. Not a booking, not a yes, not interest. A reply."));
content.push(P("That means every opener does three things:"));
content.push(Bullet("Signals you have actually looked at their business."));
content.push(Bullet("Compliments without flattering. Specific, not gushy."));
content.push(Bullet("Ends with a real question that has more than one answer."));
content.push(Spacer());

content.push(H3("What a curiosity opener sounds like"));
content.push(ScriptBlock("Hey Sarah, quick one for you. Was looking at your practice this morning. The way you have your aesthetician team structured is unusual for a $1M practice, most owners that size are still solo or splitting commissions in ways that hurt retention. Curious how that is actually working out for you. Steady, or has it gotten harder to keep the team aligned this year?"));
content.push(P("Notice what this does. It is specific. It compliments the structure without flattering the person. It ends with a question that invites a real answer (not a yes or no). It does not mention Luxora once."));

content.push(H3("What a pitch opener sounds like (do not send this)"));
content.push(ScriptBlock("Hi Sarah! Hope you are having a great week. I work with The Luxora Collective and we help med spas scale revenue. Would love to chat about how we can help your practice grow. When are you free for a quick call?"));
content.push(P("Notice why this dies. It is generic. It centers the sender, not the owner. It asks for a meeting before earning the right to ask. Every owner in your pipeline has gotten 200 of these this month."));

content.push(Spacer());
content.push(H2("Phase 2: Listen and qualify"));
content.push(P("When they reply, do not jump to the pitch. Ask one more question to find out where the friction actually lives. This is the most important part of the entire flow and it is the part most setters skip."));
content.push(Spacer());
content.push(ScriptBlock("That tracks with what Bethany Anne is seeing across the board right now. Most owners she talks to say the lead flow is actually fine, it is what happens after the lead comes in that feels inconsistent. When you think about your business right now, where does it actually break down for you most often? Is it getting consults booked, getting people to show, closing the consult, or keeping clients coming back beyond the first treatment?"));
content.push(Spacer());
content.push(Callout("Critical move",
  "Stop talking. Let them tell you. The answer they give you is the exact angle Bethany Anne will lead with on the call. Your only job in this moment is to make them feel safe enough to say the real thing."));

content.push(H2("Phase 3: Mirror the emotion, name the leak"));
content.push(P("This is where most setters lose the room. They get the owner to admit a real pain point and then immediately pivot to selling. Do not do that. Sit with what they said for a beat. Reflect it back. Then name the pattern."));
content.push(Spacer());
content.push(ScriptBlock("Yeah, that is the exhausting one. You are doing the consults yourself because nobody else closes the way you do, but that also means you are stuck in every transaction and you can feel the business hitting a ceiling. That is the pattern Bethany Anne sees in almost every practice this size. Almost no owner has a lead problem. The revenue is leaking somewhere between lead and booking, booking and consult, or consult and long-term retention. And most owners cannot see it from inside the business because they are the one running it."));
content.push(Spacer());
content.push(P("The phrase \"that is the exhausting one\" is doing more work than anything else in that paragraph. It tells the owner you heard them. It tells them you have heard it before. It tells them they are not crazy. That is what earns the next sentence."));

content.push(H2("Phase 4: Soft offer the Revenue Leak Audit"));
content.push(P("Only when they have given you two real answers. Two engaged replies means warm. One reply means keep listening. Zero replies means move on."));
content.push(Spacer());
content.push(ScriptBlock("If you are open to it, I can connect you with Bethany Anne for what she calls a Revenue Leak Audit. It is a paid consultation, $29, and you get two things from it. First, she walks you through what she would see in your specific market and where the biggest revenue gaps usually live in a practice your size. Second, you get her KPI Calculator, the same tool she uses with her active clients to find their exact numbers and pinpoint where the money is leaking before any new spend. The $29 is the qualifier, not a barrier. She only takes calls with owners who are serious enough to put a little skin in. Worst case, you walk away with a sharper view of your numbers. Best case, you find the leak that has been costing you for the last year. Want me to send the link?"));
content.push(Spacer());

content.push(H2("Phase 5: Send the link, then get out of the way"));
content.push(ScriptBlock("Perfect. Here you go: [INSERT LINK]. Grab whatever time works. Bethany Anne runs most of these herself right now. She has been in medical aesthetics for over a decade and has actually built and operated practices, so you are not talking to someone who learned this from a course. Let me know how it goes."));
content.push(Spacer());
content.push(P("Then stop typing. Do not add a P.S. Do not send a second message reinforcing the offer. Do not check in 12 hours later. They have the link. The next move is theirs."));

content.push(new Paragraph({ children: [new PageBreak()] }));

// =========================================================================
// CHANNEL: EMAIL
// =========================================================================
content.push(H1("Channel one: Email"));
content.push(P("Email is the channel where most setters sound the most like robots. It is also the channel where a human voice stands out the most. Keep messages short, lowercase the subject lines, and write like a peer who happened to notice something."));
content.push(Spacer());

content.push(H2("Email principles"));
content.push(Bullet("Subject lines are lowercase, short, and curiosity-driven. They should look like an email from a peer, not a campaign."));
content.push(Bullet("Three to five sentences per email. Never more in the first send."));
content.push(Bullet("No images, no signatures with graphics, no formatting. Plain text wins."));
content.push(Bullet("Always end with a question that takes 30 seconds to answer."));
content.push(Bullet("Never use the word \"agency.\" Never use the phrase \"hop on a quick call.\""));
content.push(Spacer());

content.push(H2("Email 1: The opener"));
content.push(P("Subject: quick question about [practice name]"));
content.push(P("Or: noticed something about [practice name]"));
content.push(P("Or: a thought on your team structure"));
content.push(Spacer());
content.push(ScriptBlock("Hey [first name],\n\nWas looking at [practice name] this morning. The way you have built out [specific thing: your aesthetician team / your membership tier / your before-and-after content / your booking flow] is unusual for a practice your size, most owners are still doing it the harder way.\n\nQuick question. From the outside it looks like you have the front of the business dialed. Behind the scenes, where does the business actually feel like it breaks down most often? Bookings, consult conversion, retention, or somewhere else?\n\nAsking because I refer owners to a team called The Luxora Collective and they have been mapping practices in your area. Yours came up.\n\n[Your name]"));

content.push(H2("Email 2: The bump (3 to 4 days later, only if no reply)"));
content.push(P("Subject: reply on the last one"));
content.push(Spacer());
content.push(ScriptBlock("Hey [first name], no rush on this.\n\nThe reason I asked is that Bethany Anne (the founder I refer to) has been seeing a pattern in practices around the $500K to $2M mark. Almost none of them have a lead problem. The revenue is leaking somewhere between the lead coming in and the client coming back, and most owners cannot see it from inside the business.\n\nIf I am off base, just say so and I will get out of your inbox. If it is at all on-base, I am happy to share what she usually finds.\n\n[Your name]"));

content.push(H2("Email 3: The walk-away (7 days after Email 2, only if no reply)"));
content.push(P("Subject: last one from me"));
content.push(Spacer());
content.push(ScriptBlock("Hey [first name],\n\nNot going to keep crowding your inbox. If the timing is wrong, the timing is wrong.\n\nIf you ever want to know where money is quietly leaking in a practice your size, Bethany Anne runs a 45-minute Revenue Leak Audit for $29. She walks you through exactly where the gaps usually are and you keep the KPI Calculator afterward. Link is here if you ever want it: [LINK].\n\nEither way, wish you a good rest of the quarter.\n\n[Your name]"));
content.push(Spacer());
content.push(Callout("Why the walk-away works",
  "The walk-away email outperforms the bump email almost every time. It releases pressure, gives them permission to ignore you, and leaves the door open. Owners who were on the fence often book after this exact email."));

content.push(H2("Email reply scripts (when they actually respond)"));
content.push(H3("If they reply with a real pain point"));
content.push(ScriptBlock("Yeah, that is the one Bethany Anne sees most often in practices your size. [Mirror what they said in one sentence]. The reason it persists is usually [name the underlying pattern: the front desk is undertrained for sales / there is no real package architecture / consults are converting but retention drops off after treatment two].\n\nIf you want, I can connect you with Bethany Anne for her Revenue Leak Audit. It is a paid 45-minute consultation, $29, and she walks you through exactly where the gaps are in your specific market plus you keep her KPI Calculator. Want me to send the link?"));

content.push(H3("If they reply with skepticism or pushback"));
content.push(ScriptBlock("Totally fair. I would push back too if a stranger emailed me out of nowhere.\n\nThe quick version: Bethany Anne has been in medical aesthetics for over a decade and has actually built and run practices, not just consulted on them. The Revenue Leak Audit is $29 because she only wants to talk to owners who are serious enough to put a little skin in. If after 45 minutes you think it is generic or unhelpful, that is a $29 lesson. If it is the real thing, you save six figures.\n\nNo pressure either way. Just want to make sure you have it if it is useful."));

content.push(H3("If they say \"send me info\""));
content.push(ScriptBlock("I could send a deck, but honestly the deck will not tell you what is actually happening in your specific practice. That is the whole point of the audit. It is built around your numbers, your market, your team, not a generic case study.\n\nIf you want the short version, the site is theluxoracollective.co. But the call is where you actually find out if it is a fit. $29, 45 minutes, and you keep the KPI Calculator either way. Want the link?"));

content.push(new Paragraph({ children: [new PageBreak()] }));

// =========================================================================
// CHANNEL: PHONE
// =========================================================================
content.push(H1("Channel two: Phone"));
content.push(P("Phone is the highest-conversion channel in the entire stack and the channel most setters avoid. If an owner picks up, you have 15 seconds to earn the next 60. If you earn the next 60, you have a real conversation."));
content.push(Spacer());

content.push(H2("Phone principles"));
content.push(Bullet("Call between 10am and 11:30am local, or between 2pm and 3:30pm local. Avoid Mondays and Fridays."));
content.push(Bullet("Open with their name, your name, and the reason you are calling. In that order."));
content.push(Bullet("Pattern-interrupt the first 10 seconds. They are expecting a pitch. Give them a question."));
content.push(Bullet("Never start with \"how are you today.\" That phrase is the verbal flag for cold sales."));
content.push(Bullet("Match their pace. If they sound rushed, you sound rushed. If they slow down, you slow down."));
content.push(Spacer());

content.push(H2("Phone script: When the owner picks up"));
content.push(ScriptBlock("Hey [first name], this is [your name]. I know I am calling out of the blue so I will be quick. I refer med spa owners to a team called The Luxora Collective and I was actually looking at [practice name] this morning. Is now a bad time for me to ask one question, or should I try you back?"));
content.push(P("That last line is the lock. \"Is now a bad time\" gives them an easy out, which paradoxically makes them more likely to say no, it is fine, keep going. If they say it is a bad time, you ask when to call back and you call back."));
content.push(Spacer());

content.push(H3("If they give you the green light"));
content.push(ScriptBlock("Appreciate it. So the one question is this. From the outside, it looks like you have built a real practice. But Bethany Anne, the founder I refer to, sees a pattern in practices your size where the lead flow is actually fine but everything after the lead, the booking, the consult, the retention, is where money is quietly leaking. Does any of that sound familiar in your business, or are you in a different spot?"));

content.push(H3("If they say yes to one of those friction points"));
content.push(ScriptBlock("Yeah, that is the one I hear most. [Mirror what they said]. The reason Bethany Anne is good at this is she has actually run med spas, not just consulted on them. She runs a paid 45-minute call she calls a Revenue Leak Audit, $29, and she walks owners through exactly where the gaps usually are plus you keep her KPI Calculator after. Would it be useful for me to text you the link so you can grab a time that works?"));

content.push(H3("If they push back on the price"));
content.push(ScriptBlock("Totally get it, most people charge nothing for these. That is exactly why she charges $29. It filters out tire-kickers so the calls she does take are higher quality. And for $29 you get the diagnostic plus the calculator, so even if you never work with her again, it pays for itself. Want me to text you the link?"));

content.push(H3("If they say \"send me an email\""));
content.push(ScriptBlock("For sure, I will send you something. But quick question. If I send you something and you read it, what would actually move you to book a call? Because honestly, if the answer is nothing, I would rather not waste either of our time. I want to send something you will actually use."));
content.push(P("That question is a soft mirror. It puts the decision back in their court. Most owners either say \"actually you can just text me the link\" or they go quiet and you send a short follow-up email."));

content.push(H2("Voicemail script (when they do not pick up)"));
content.push(ScriptBlock("Hey [first name], [your name] here. Reaching out about [practice name]. I refer owners to a team called The Luxora Collective and yours came up when they were mapping practices in your area. Not a pitch, just had a question for you. I will follow up with a text and an email so you have options. Talk soon."));
content.push(P("Keep voicemails under 20 seconds. The point is not to sell, it is to make your name familiar so the follow-up text and email land warmer."));

content.push(new Paragraph({ children: [new PageBreak()] }));

// =========================================================================
// CHANNEL: TEXT
// =========================================================================
content.push(H1("Channel three: Text message"));
content.push(P("Text is the most intimate channel you have. It also has the highest open rate of anything in this playbook. Use it after a phone call, a voicemail, or when the owner has given you their number through a form or a referral. Do not cold-text someone whose number you found on a database."));
content.push(Spacer());

content.push(H2("Text principles"));
content.push(Bullet("Two to four sentences max."));
content.push(Bullet("Lowercase. Casual. No corporate punctuation."));
content.push(Bullet("Always say who you are in the first text. Always."));
content.push(Bullet("Never send the booking link in the first text."));
content.push(Bullet("Mirror their texting style. If they use periods, you use periods. If they do not, you do not."));
content.push(Spacer());

content.push(H2("Text 1: Post-voicemail follow-up"));
content.push(ScriptBlock("hey [first name], this is [your name], just left you a voicemail. no rush. quick question about [practice name] when you have a sec. text is fine if easier than a call."));

content.push(H2("Text 2: If they respond \"what is up\" or \"who is this\""));
content.push(ScriptBlock("good to hear back. so the quick one, i refer owners to bethany anne at the luxora collective and she has been mapping practices in your area. yours came up. just wanted to ask, from the outside it looks like you have the front of the business handled, but where does it actually break down for you most often: bookings, consult conversion, or retention?"));

content.push(H2("Text 3: If they engage with a real answer"));
content.push(ScriptBlock("yeah that is the one bethany anne sees most in practices your size. she runs a 45-minute revenue leak audit, $29, walks you through exactly where the gaps are plus you keep her kpi calculator. want me to send the link?"));

content.push(H2("Text 4: If they say yes, send the link"));
